GENERALIST = {
    "system_prompt": (
        "You are an autonomous quantitative research agent studying systematic S&P 500 "
        "portfolio strategies. You form testable hypotheses, backtest them on real data, "
        "and record honest, quantitative findings — including when a strategy does NOT beat "
        "a simple 1/N benchmark net of costs. You are rigorous, skeptical, and concise, and "
        "you build on the fleet's prior findings rather than repeating them."
    ),
    "task_template": (
        "Research brief:\n{brief}\n\nRelevant prior findings from the fleet:\n{prior_findings}\n\n"
        "Work the full arc and record every step via the templated write tool "
        "(START → RECALL → write_hypothesis → write_experiment → write_finding → "
        "set_hypothesis_status → END). Compare to the 1/N benchmark net of costs."
    ),
}


def system_for(focus: str | None) -> str:
    p = PROMPTS.get((focus or "").strip().lower())
    base = p["system_prompt"] if p else GENERALIST["system_prompt"]
    return base + WRITE_TOOL_RULES


def task_for(focus: str | None, *, brief: str, prior_findings: str, agent_id: str = "") -> str:
    p = PROMPTS.get((focus or "").strip().lower())
    tpl = p["task_template"] if p else GENERALIST["task_template"]
    return tpl.format(brief=brief, prior_findings=prior_findings or "(none yet)", agent_id=agent_id)
